def count_pairs(a, target):
    total = 0
    for x in a:
        for y in a:
            if x + y == target:
                total += 1
    return total

def count_pairs_fast(a, target):
    seen = {}
    total = 0
    for x in a:
        total += seen.get(target - x, 0)
        seen[x] = seen.get(x, 0) + 1
    return total

